import {createExamArchive,retryExamDecision,examMastery} from './guided-exam-history.mjs';
import {createGuidedExam,guidedExamAct,guidedExamScore,validGuidedExam} from './guided-exam-model.mjs';
import {createGuidedHistory} from './repair-guided-history.mjs';
import {createGuidedSpacing,guidedSpacingRows} from './guided-spacing.mjs';
import {guidedScore,guidedRecommendation,guidedChoose,guidedNext,guidedHint} from './repair-guided.mjs';
import {faultCatalog} from './energy-faults.mjs';
let storage;try{storage=localStorage;}catch{}
const archive=createExamArchive(storage);let inspected=null,retry=null;const current=()=>inspected||exam;
const history=createGuidedHistory(storage),spacing=createGuidedSpacing(storage),key='mecanica.guided-exam.v1';let exam=null,index=0,ready=false,review=null,warning='';
try{const s=JSON.parse(storage.getItem(key)||'null');if(validGuidedExam(s))exam=s;}catch{warning='No se pudo recuperar el intento anterior.';}
const host=document.querySelector('#guidedExam'),frame=document.querySelector('#lab'),names={transformload:'Transformador',opamp:'Operacional',relief:'Hidráulica'};
function persist(){try{storage.setItem(key,JSON.stringify(exam));}catch{warning='Este examen solo se conserva durante esta sesión.';}}
function finish(){if(exam?.status!=='finished')return;archive.save(exam);for(const c of exam.cases)history.save(c);spacing.sync(guidedSpacingRows(history.all()));}
function send(){if(!ready)return;if(retry){frame.contentWindow.postMessage({type:'energy-exam-case',faults:retry.faults,level:retry.level,primaryRepairedIds:retry.fixed,repairedIds:retry.phase==='question'?retry.fixed:retry.recommendedIds,paused:retry.phase==='question'},location.origin);return;}const exam=current();if(!exam)return;const c=exam.cases[index];const message={type:'energy-exam-case',faults:c.faults,level:c.level};if(exam.status==='active'){Object.assign(message,{repairedIds:c.fixed,paused:c.phase==='question'});}else{const step=c.steps[review?.step??0],before=review?.before===true;Object.assign(message,{primaryRepairedIds:before?step.before:step.after,repairedIds:before?step.before:step.recommendedIds,paused:before});}frame.contentWindow.postMessage(message,location.origin);}
function view(i,r=null){index=i;review=r;frame.hidden=false;const url='index.html?id='+(retry?.lab||current().cases[i].lab)+'&exam=1';if(frame.getAttribute('src')===url)send();else{ready=false;frame.src=url;}render();}
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==frame.contentWindow)return;if(e.data?.type==='energy-exam-ready'){ready=true;send();render();}if(e.data?.type==='concept-height'&&Number.isFinite(e.data.height))frame.style.height=Math.max(700,Math.min(14000,e.data.height))+'px';});
const actionLabel=(c,action,choice)=>action==='verify'?'Verificar todas las averías':faultCatalog[c.lab].find(f=>f.id===choice)?.repair||'Intervención';
function render(){renderArchive();const exam=current();host.replaceChildren();const el=(tag,text,parent=host)=>{const n=document.createElement(tag);n.textContent=text;parent.append(n);return n;};const button=(text,fn,parent=host)=>{const b=el('button',text,parent);b.onclick=fn;return b;};for(const w of [warning,history.warning(),spacing.warning(),archive.warning()])if(w)el('p',w);
 if(retry){renderRetry(el,button);return;}
 if(!exam){el('p','100 puntos por caso, −15 por decisión incorrecta, mínimo 0. La nota es la media de los tres casos. Se conservan los avances al recargar; el plan se actualiza solo al terminar.');button('Comenzar examen guiado',()=>{startExam();});return;}
 const c=exam.cases[index];
 if(exam.status==='active'){el('h2','Caso '+(index+1)+' / 3 · '+names[c.lab]);el('p','A: referencia normal · B: resultado de tus acciones. Las recomendaciones permanecen ocultas hasta completar los tres casos.');
 const act=(a,f)=>{guidedExamAct(exam,index,a,f);persist();if(exam.status==='finished'){finish();view(0,{step:0,before:true});}else if(c.done)view(exam.cases.findIndex(g=>!g.done));else{send();render();}};
 if(c.phase==='question'){el('h3','En pausa · ¿qué harías ahora?');for(const f of faultCatalog[c.lab]){const b=button(f.repair,()=>act('repair',f.id));b.dataset.examChoice=f.id;b.disabled=!ready;}const b=button('Verificar todas las averías',()=>act('verify'));b.dataset.examVerify='';b.disabled=!ready;}
 else{el('p','Decisión registrada. Observa la respuesta del banco B. Si este caso continúa, todavía requiere intervención y verificación.');const b=button('Siguiente decisión · pausar',()=>act('next'));b.dataset.examNext='';b.disabled=!ready;}return;}
 el('h2','Examen completado · '+guidedExamScore(exam)+'/100');el('p','Resultados guardados en tu progreso guiado. Errores por intervención, dificultad recomendada y próximos repasos actualizados.');
 exam.cases.forEach((g,i)=>{const card=el('article','');card.className='guided-exam-case';el('h3',names[g.lab]+' · '+guidedScore(g)+'/100 · '+g.errors+' errores',card);el('p',g.adaptation,card);g.steps.forEach((s,j)=>{const rec=guidedRecommendation({...g,fixed:s.before});el('p','Decisión '+(j+1)+': '+actionLabel(g,s.action,s.choice)+' · '+(s.correct?'Correcta':'−15 puntos'),card);el('p','Recomendada: '+actionLabel(g,rec.action,rec.choice)+'.',card);const why=s.correct?'Acción útil; un orden alternativo válido no resta puntos.':s.kind==='premature'?'Verificaste antes de corregir todas las causas.':s.kind==='repeated'?'Repetiste una reparación que ya estaba aplicada.':'Interviniste una causa que no estaba presente.';el('p',why,card);const before=button('Antes de decidir',()=>view(i,{step:j,before:true}),card);before.dataset.reviewBefore=i+':'+j;const after=button('Comparar decisiones',()=>view(i,{step:j,before:false}),card);after.dataset.reviewAfter=i+':'+j;});});
 el('h3','Revisión · '+names[c.lab]+' · decisión '+((review?.step??0)+1));el('p','A muestra tu elección; B, la recomendación desde el mismo estado previo. Antes de decidir ambos se pausan. Después, las lecturas y las piezas comparten el reloj; no se reproducen tiempos reales de intervención.');
 const a=el('a','Abrir mi plan guiado actualizado');a.href='repair-exam.html?v=guided-weekly#guidedHistory';if(!inspected)button('Nuevo examen guiado',()=>{startExam();});
}
function startExam(){inspected=null;retry=null;exam=createGuidedExam(history.all());persist();view(0);}
function renderRetry(el,button){
 el('h2','Repaso de decisión · '+names[retry.lab]);el('p','Mismo estado previo al error. A: tu intervención · B: recomendada. El repaso no modifica la nota del examen.');
 const act=(a,f)=>{if(a==='hint')guidedHint(retry);else if(a==='next')guidedNext(retry);else guidedChoose(retry,a,f);if(retry.done){history.save(retry);spacing.sync(guidedSpacingRows(history.all()));}send();render();};
 if(retry.phase==='question'){el('h3','En pausa · ¿qué intervención harías?');for(const f of faultCatalog[retry.lab]){const b=button(f.repair,()=>act('repair',f.id));b.disabled=!ready;b.dataset.retryChoice=f.id;}const b=button('Verificar todas las averías',()=>act('verify'));b.disabled=!ready;b.dataset.retryVerify='';const h=button('Pista (−10 puntos)',()=>act('hint'));h.disabled=retry.hintUsed||!ready;}
 if(retry.feedback)el('p',retry.feedback);el('p','Puntuación del repaso: '+guidedScore(retry)+'/100');
 if(retry.done)el('p','Repaso guardado y plan actualizado. La nota original se conserva.');else if(retry.phase==='feedback')button('Siguiente decisión · pausar',()=>act('next'));
 button('Volver al examen',()=>{retry=null;view(index,review);});
}
function renderArchive(){
 const root=document.querySelector('#examArchive');root.replaceChildren();const add=(tag,text,parent=root)=>{const n=document.createElement(tag);n.textContent=text;parent.append(n);return n;};const rows=archive.all();add('h2','Tu historial de exámenes guiados');add('p','Últimos 50 exámenes completos, guardados en este navegador. Los repasos no alteran estas notas.');
 if(!rows.length){add('p','Completa tu primer examen para comparar resultados.');return;}
 const list=add('div','');list.className='exam-score-grid';rows.forEach((e,i)=>{const card=add('article','',list);const score=guidedExamScore(e),previous=i?guidedExamScore(rows[i-1]):null;add('h3',new Date(e.finishedAt).toLocaleDateString('es-CO')+' · '+score+'/100',card);const meter=add('meter','',card);meter.min=0;meter.max=100;meter.value=score;meter.setAttribute('aria-label','Nota '+score+' de 100');add('p',(previous===null?'Primer examen':(score-previous>=0?'+':'')+(score-previous)+' puntos frente al anterior')+' · '+e.cases.reduce((n,c)=>n+c.errors,0)+' errores',card);add('p','Niveles: '+e.cases.map(c=>c.level==='combined'?'combinado':c.level==='intermittent'?'intermitente':'básico').join(' / '),card);const b=add('button','Revisar examen',card);b.onclick=()=>{retry=null;inspected=e;view(0,{step:0,before:true});host.scrollIntoView({block:'start'});};});
 add('h3','Dominio por intervención');add('p','En exámenes: “Consistente” requiere al menos 3 decisiones y ningún error en las últimas 5. Compara también los niveles de dificultad.');
 for(const item of examMastery(rows)){add('p',names[item.lab]+' · '+actionLabel(item,item.action,item.choice)+' — '+item.recentCorrect+'/'+item.recentN+' aciertos recientes · '+item.errors+' errores de '+item.total+' · '+(item.mastered?'Consistente':'En práctica'));}
 add('h3','Decisiones para repasar');let count=0;for(const e of [...rows].reverse())e.cases.forEach((c,i)=>c.steps.forEach((s,j)=>{if(s.correct)return;count++;const b=add('button',new Date(e.finishedAt).toLocaleDateString('es-CO')+' · '+names[c.lab]+' · decisión '+(j+1)+': '+actionLabel(c,s.action,s.choice));b.dataset.retryDecision=e.id+':'+i+':'+j;b.onclick=()=>{inspected=e;retry=retryExamDecision(e,i,j);view(i,{step:j,before:true});host.scrollIntoView({block:'start'});};}));if(!count)add('p','No hay decisiones fallidas en tus exámenes.');
 if(inspected||retry){const b=add('button',exam?.status==='active'?'Continuar examen en curso':'Volver al último examen');b.onclick=()=>{inspected=null;retry=null;if(exam)view(exam.status==='active'?exam.cases.findIndex(c=>!c.done):0);else render();};}
}
if(exam){finish();view(exam.status==='active'?Math.max(0,exam.cases.findIndex(c=>!c.done)):0);}else render();
window.guidedExamDebug=()=>({exam,index,review,ready,inspected,retry,archive:archive.all()});
